const r=await tools.exec_command({cmd:"@'
from pathlib import Path
from datetime import datetime,UTC
import subprocess,json,hashlib
p=Path('docs/audit/superagent/capability-independent-audit.json')
old=p.read_text(encoding='utf-8');d=json.loads(old)
sha=lambda b:hashlib.sha256(b).hexdigest()
canonical=lambda v:json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':'))
def entry(f):
 b=f.read_bytes();return {'path':f.as_posix(),'sha256':sha(b),'bytes':len(b)}
source=[entry(f) for f in sorted(Path('backend/src').rglob('*.py'))]
status=subprocess.check_output(['git','status','--porcelain=v1','-uall','--','backend/tests','backend/scripts'],text=True,encoding='utf-8')
paths=sorted({x[3:] for x in status.splitlines() if x[3:].endswith('.py') and Path(x[3:]).is_file()})
validation=[entry(Path(x)) for x in paths]
all_validation=[entry(f) for root in [Path('backend/scripts'),Path('backend/tests')] for f in sorted(root.rglob('*.py'))]
changes=[]
for cat,key,current in [('source','source_inventory',source),('validation','modified_validation_inventory',validation)]:
 prior={x['path']:x['sha256'] for x in d[key]['files']};latest={x['path']:x['sha256'] for x in current}
 for path in sorted(set(prior)|set(latest)):
  if prior.get(path)!=latest.get(path):changes.append({'category':cat,'path':path,'old_sha256':prior.get(path),'new_sha256':latest.get(path)})
now=datetime.now(UTC).isoformat()
oldmanifest=d['manifest_sha256']
d['source_inventory']['files']=source;d['source_inventory']['file_count']=len(source)
d['modified_validation_inventory']['files']=validation;d['modified_validation_inventory']['file_count']=len(validation)
d['all_validation_inventory']={'scope':'all backend/scripts/**/*.py and backend/tests/**/*.py current frozen working-copy bytes','file_count':len(all_validation),'files':all_validation,'sha256':sha(canonical(all_validation).encode())}
manifest_payload={'source':source,'modified_validation':validation,'all_validation':all_validation}
d['manifest_sha256']=sha(canonical(manifest_payload).encode())
d['manifest_definition']='sha256 of canonical UTF-8 JSON {source,modified_validation,all_validation}; each list contains ordered path/sha256/bytes objects. Prior manifest definitions/hashes remain in refresh history.'
reportfiles=sorted(f for f in p.parent.glob('*capability-*.json') if f.name!=p.name)
d['retained_report_hash_inventory']={'scope':'All currently saved original capability experiment and supplemental JSON reports, excluding this audit; content status is not changed by hash capture','file_count':len(reportfiles),'files':[entry(f) for f in reportfiles]}
xmls=sorted(p.parent.glob('*.xml'))
d['retained_test_report_hash_inventory']={'scope':'Saved XML evidence hashes only; no result is inferred for the currently running frozen suite','file_count':len(xmls),'files':[entry(f) for f in xmls]}
supfile=p.parent/'REDACTED.json';sup=json.loads(supfile.read_text(encoding='utf-8'))
retained_ids={x['run_id'] for x in d['retained_real_task_experiments']}
for name in ['20261115T213801Z-capability-development-1cf69f','20261115T214924Z-capability-adaptive-35c07f']:
 if name in retained_ids:continue
 f=p.parent/(name+'.json');raw=json.loads(f.read_text(encoding='utf-8'));m=raw['metrics']
 projection={'path':f.as_posix(),'sha256':sha(f.read_bytes()),'run_id':name,'execution_mode':raw['execution_mode'],'upstream_identity':raw['upstream_identity'],'strategy':raw['strategy'],'status':raw['status'],'failure_code':raw.get('failure_code'),'source_sha256_at_execution':raw['source_sha256'],'limits':raw['limits'],'model_calls':m['model_calls'],'admission_states':m['admission_states'],'charged_tokens':m['charged_tokens'],'known_charged_tokens':m['known_charged_tokens'],'unknown_usage_attempts':m['unknown_usage_attempts'],'cost_microunits':m['cost_microunits'],'cost_currency':m['cost_currency'],'tools':{'calls':m['tool_calls'],'states':m['tool_states'],'integrity':m['receipt_integrity_rate']},'workers':m['workers_by_state'],'core_quest_completion':m['core_completed_quest_rate'],'acceptance_checks':raw['checks'],'context_metadata':raw['context_metadata'],'snapshot_sha256':m['snapshot_sha256'],'acceptance_success':False,'acceptance_scope':'retained_failed_experiment_only; tool success, Reviewer PASS or Core state does not establish L1/L2/L3 acceptance'}
 if name.endswith('35c07f'):projection['independent_supplement']={'path':supfile.as_posix(),'sha256':sha(supfile.read_bytes()),'does_not_reclassify_acceptance':True}
 d['retained_real_task_experiments'].append(projection)
d['retained_task_totals']={**sup['retained_task_totals'],'provenance':'independent mode=ro transaction aggregates for six stopped historical experiment databases in retained independent supplemental','settled_calls':85,'reserved_calls':1,'interpretation':'All six original failed runs remain failed. Current running fresh adaptive is excluded. Unknown historical outcome remains charged/reserved and must not be replayed.'}
d['retained_database_accounting_audit']={'path':supfile.as_posix(),'sha256':sha(supfile.read_bytes()),'run_count':6,'database_read_mode':'sqlite_mode_ro_single_transaction_per_database','provider_calls':0,'does_not_reclassify_acceptance':True}
d.setdefault('pending_evidence_history',[]).append({'as_of_previous_refresh':d.get('last_refreshed_at'),'pending_real_provider_scenarios':d.get('pending_real_provider_scenarios',[])})
d['pending_real_provider_scenarios']=[{'run_id':'20261115T215924Z-capability-adaptive-45f4e4','strategy':'adaptive','status':'parent_reports_running','session_id':98197,'result':None,'acceptance_success':None,'source':'Parent freeze/start assignment; final live result intentionally left null until parent notifies. Excluded from retained completed experiment totals.'}]
d['frozen_test_run']={'path':'docs/audit/superagent/capability-backend-frozen.xml','status':'parent_reports_running','session_id':48778,'result':None,'passed':None,'failed':None,'skipped':None,'source':'Parent freeze/start assignment; no final result inferred from partial XML or other suites.'}
d['frozen_source_validation']={'captured_at':now,'source_and_modified_validation_manifest_sha256':d['manifest_sha256'],'state':'awaiting_final_live_and_full_suite_results','final_source_unchanged':None,'provider_calls_made_by_this_refresh':0,'production_files_changed_by_this_refresh':False}
d['uncompleted_or_unestablished']=[x for x in d['uncompleted_or_unestablished'] if x!='Third full-suite completed result at audit snapshot']+['Final frozen full-suite result and source drift comparison']
d['limitations']=[x for x in d['limitations'] if not x.startswith('Stored report metrics') and not x.startswith('Latest source manifest') and not x.startswith('Root may append')]
d['limitations']+=['Six stopped historical experiment databases were independently aggregated in mode=ro transactions; their report hashes and supplemental identify those observations. Raw upstream usage remains unverified.','The current frozen source, driver, scenarios and tests are hashed here. The running fresh adaptive and frozen full-suite results remain null until explicit completion notification; historical failed results are retained.','Source/test/script snapshots are read twice. Hash history retains all prior snapshots and no report is overwritten.']
d['inventory_refresh_history'].append({'recorded_at':now,'reason':'Parent confirms production/driver/scenarios/test freeze and requests manifest-only capture while fresh live acceptance and frozen full backend suite run. Earlier failed reports retained; no Provider/test/production work performed by auditor.','old_audit_file_sha256':sha(old.encode()),'old_manifest_sha256':oldmanifest,'new_manifest_sha256':d['manifest_sha256'],'manifest_scope_extended_to_all_validation':True,'changes':changes})
d['last_refreshed_at']=now
second_source=[entry(f) for f in sorted(Path('backend/src').rglob('*.py'))]
second_validation=[entry(Path(x)) for x in paths]
second_all=[entry(f) for root in [Path('backend/scripts'),Path('backend/tests')] for f in sorted(root.rglob('*.py'))]
d['inventory_changed_during_latest_refresh']=[x['path'] for one,two in [(source,second_source),(validation,second_validation),(all_validation,second_all)] for x,y in zip(one,two) if x!=y]
