const data=load("comparison_raw");
const resources=data.resources;
const sourceSemantics="Composite SHA-256 from verify_superagent_capability.source_digest(): concatenate repository-relative POSIX path bytes and file bytes for sorted backend/src/**/*.py, then verify_superagent_capability.py, capability_sprint_scenarios.py and capability_sprint_metrics.py in that order. This is not the driver-file SHA-256 and does not identify frontend or tests.";
const metricSemantics={
 observed_event_span_seconds:"Copied unchanged from the original metrics. Span of observed Core event timestamps; not end-to-end wall latency, CPU time, or concurrent CPU execution.",
 original_harness_elapsed_seconds:"Original top-level elapsed_seconds, separately labelled; includes harness/startup/shutdown-drain overhead and is not the event span.",
 repair_events:"Original self-repair event count. Keep distinct from cumulative worker_repair_counters; do not sum them.",
 worker_repair_counters:"Original Worker repair counters, which can include other revision/rework paths.",
 cost_microunits:"Unknown in all six original reports; retained as null, never zero or estimated from tokens.",
 receipt_integrity_rate:"Stored receipt hash/binding checks only; not external truth or semantic evidence completeness.",
 recovered_run_current_success_rate:"Zero recovery-event denominator in these reports leaves recovery efficacy unknown; no causal recovery claim.",
 core_completed_quest_rate:"Core terminal status only; not independent task correctness or overall scenario acceptance.",
 review_verdicts:"Core independent-review model verdicts; do not confuse with planned specialist Reviewer Workers or independent host artifact checks.",
 admission_states:"Model-call settlement only. Does not resolve unknown external tool effects; shutdown_drain and blocked reasons remain separately visible.",
 source_refs:"Copied original bounded evidence references, with original source_refs_omitted retained."
};
const l2Criteria={
 provenance:"Derived from persisted L2 scenario descriptor checks, expected_artifacts and task prompt. These are comparison fields, not a criteria/class field in the original report.",
 deliverable:"research.json with summary; citations covering all three fixed-revision sources with exact SHA-256, original line ranges and verbatim nonempty quotes; at least two comparison rows, two risks and two recommendations, with valid comparison source references.",
 source_preservation:"Read actual fixed source files with governed tools; keep inputs unchanged; outputs under owned work/<quest_id>/; receipt/hash-bound revisions.",
 quality_boundary:"Exact quotes establish source provenance, not correctness of design inference. Original independent host check explicitly does not assess semantic quality.",
 independent_review:"Core independent Reviewer verdict is separate from any selected specialist Reviewer Worker."
};
const l3Criteria={
 provenance:"Derived from persisted L3 scenario descriptor checks, expected_artifacts and task prompt.",
 deliverables:["candidate.py","test_candidate.py","development.json"],
 implementation:"Frozen Record(key:str,value:int) and normalize_records: list of dictionaries only; non-boolean integers; strip/casefold nonempty keys; keep last duplicate; lexicographically sort; no input mutation; malformed inputs raise ValueError.",
 execution:"Real exact-manifest CPython unittest with separate exact approval, successful test receipt bound to final candidate hash, nonempty exact test_receipt_ids, and independent host holdout.",
 repair:"Observe actual failure/correction or explicitly report that no failure was reproduced; no invented test result."
};
function freezeFor(index){
 if(index===2) return {source_freeze:null,acceptance_protocol:null,binding_note:"Original composite source hash is preserved. No matching pre-run freeze/protocol is bound in this comparison; do not associate the later continuation freeze with this earlier source."};
 if(index<=1 || index===3) return {source_freeze:resources["capability-continuation-source-freeze.json"],acceptance_protocol:resources["capability-continuation-protocol.json"]};
 if(index===4) return {source_freeze:resources["capability-repair-source-freeze.json"],acceptance_protocol:resources["capability-repair-acceptance-protocol.json"]};
 return {source_freeze:resources["capability-final-source-freeze.json"],acceptance_protocol:resources["capability-final-continuity-protocol.json"]};
}
const notes=[
 ["One actual Research Worker satisfied the single condition. All original top-level checks passed. The independent artifact checker passed structural/exact-citation checks but semantic_quality_assessed=false.","No context archive or recovery event occurred in this condition; do not infer compaction or recovery quality from this successful L2."],
 ["The selected sequential Research -> Architect condition was attempted, not completed: actual_worker_count=1 and actual_roles=[research_1]. Architect did not start.","Original terminal states remain review_pending/running; two NEEDS_REVISION verdicts and bounded_scenario_deadline remain failed. The report contains no independent artifact-check result; missing is not a pass or independently judged failure.","Review/revision blockage and Router reflection confound attributing the entire difference to team topology."],
 ["Hierarchical L2 selected Research/Architect plus a dependent specialist Reviewer, but only Research and Architect started; L3 started one Coding Worker.","Original checks record pass-through, same-state host restart, compaction of real history and typed Recall. Original continuity.recall_incomplete=true; those flags do not establish complete source-correct long-term continuity.","L3 independent host holdout passed seven tests, yet original source_bound_tests_L3=false and final Router notification failed. Overall acceptance remains failed."],
 ["Neither task was admitted; no Worker, tool or review ran. Original failure is core_api_status_409. Do not count the requested team as an observed execution.","Later Router-protocol diagnostics/fixes do not retroactively disclose the unretained raw response or turn the original failure into a pass."],
 ["L2 started Research and Architect; the dependent specialist Reviewer did not start. L3 was not admitted.","Original report has no independent final-artifact check. Later supplemental artifact-only checks are separate observations and cannot change original status.","Original failure router_did_not_create_independent_task remains failed. Do not infer original pass-through, restart or Recall acceptance from archive_count alone."],
 ["L2 selected dependent Research -> Architect under a hierarchical label but only Research started; L3 started Coding. The original observed_team_condition_L2=false remains false.","Both pass-through checks passed, while original Workers ended blocked and both Quests remained running. Recorded blocked reasons context_budget and tool_unresolved are preserved.","All 28 model calls settled; model settlement does not authorize replay of any unknown tool operation. No original independent final-artifact acceptance was recorded."]
];
function row(entry,index){
 const r=entry.report;
 const acceptance={
  field_provenance:"Derived comparison metadata; original reports contain neither a criteria nor a class field.",
  scenarios:entry.descriptors,
  task_requirements:{L2:l2Criteria},
  team_condition:index===0?"Exactly one Worker; single baseline overrides the generic scenario descriptor multi_specialist_analysis label.":index===1?"Exactly two sequential specialists Research -> Architect, success-dependent predecessor handoff, both actually started.":"Dynamic useful specialist choice for L2, plus independent L3 development task; requires actual distinct-task overlap and complete joint continuity acceptance, not a fixed team label.",
  original_checks:r.checks
 };
 if(r.scenario_levels.includes("L3")) acceptance.task_requirements.L3=l3Criteria;
 const actual={};
 for(const level of r.scenario_levels){
  const t=r.tasks?.[level]; const obs=t?.team_observation;
  actual[level]={
   task_admitted:!!t,
   selected_and_actual_original:obs??null,
   planned_downstream_not_started:!obs?[]:index===1||index===5&&level==="L2"?["architect"]:index===2||index===4?level==="L2"?["reviewer"]:[]:[],
   downstream_derivation:"Compared selected assignment roles and actual_roles in the original report; numeric role suffixes identify actual specialist Workers. A missing actual role is not a completed downstream sample.",
   original_independent_check_attempted:t?.independent_check_attempted??null,
   original_independent_check:t?.independent_check??null,
   original_test_receipt_check:t?.test_receipt_check??null
  };
 }
 const result={
  run_id:r.run_id, original_report:entry.binding,
  evidence_class:{
   class:"real_provider_execution_with_programmatic_read_only_metrics",
   provenance:"Derived classification from original execution_mode=live and metrics.provenance=programmatic_read_only_core_evidence; not an original class field.",
   upstream_identity:r.upstream_identity,
   mock_execution:false,
   independent_checks:"Only original per-task independent_check fields are copied; later supplemental reports are not merged into original outcomes.",
   continuity_injection:r.continuity?.provenance??null
  },
  source_binding:{source_sha256:r.source_sha256,source_digest_semantics:sourceSemantics,...freezeFor(index)},
  criteria:acceptance,
  strategy:r.strategy,scenario_levels:r.scenario_levels,context_metadata:r.context_metadata,limits:r.limits,
